class Economy {
  constructor() {
    this.towns = [
      { name: 'Village', goods: ['Grain', 'Wood'], supply: [100, 50], demand: [50, 30] },
      { name: 'Town', goods: ['Iron', 'Cloth'], supply: [70, 60], demand: [40, 50] },
      { name: 'City', goods: ['Gold', 'Spices'], supply: [30, 80], demand: [60, 70] },
      { name: 'Fortress', goods: ['Weapons', 'Leather'], supply: [50, 40], demand: [30, 40] },
      { name: 'Hamlet', goods: ['Fruits', 'Herbs'], supply: [80, 90], demand: [20, 30] }
    ];
  }

  updatePrices() {
    this.towns.forEach(town => {
      town.goods.forEach((good, index) => {
        const supply = town.supply[index];
        const demand = town.demand[index];
        const basePrice = 10;
        const priceChange = (demand - supply) / 10;
        town.supply[index] += Math.random() * 5 - 2.5; // Random fluctuation
        town.demand[index] += Math.random() * 5 - 2.5; // Random fluctuation
        town.price = basePrice + priceChange;
      });
    });
  }

  getPrice(townName, good) {
    const town = this.towns.find(t => t.name === townName);
    if (!town) return null;
    const index = town.goods.indexOf(good);
    if (index === -1) return null;
    return town.price;
  }
}

class Town {
  constructor(name, goods, supply, demand) {
    this.name = name;
    this.goods = goods;
    this.supply = supply;
    this.demand = demand;
  }

  getGoodsInfo() {
    return this.goods.map((good, index) => ({
      good,
      supply: this.supply[index],
      demand: this.demand[index]
    }));
  }
}

class Player {
  constructor(money, inventory, wagonCapacity) {
    this.money = money;
    this.inventory = inventory;
    this.wagonCapacity = wagonCapacity;
    this.wagonUpgrades = 0;
  }

  buy(good, quantity, price) {
    const cost = quantity * price;
    if (this.money >= cost && this.canCarry(quantity)) {
      this.money -= cost;
      this.inventory[good] = (this.inventory[good] || 0) + quantity;
      return true;
    }
    return false;
  }

  sell(good, quantity, price) {
    if (this.inventory[good] >= quantity) {
      this.money += quantity * price;
      this.inventory[good] -= quantity;
      return true;
    }
    return false;
  }

  upgradeWagon() {
    this.wagonUpgrades++;
    this.wagonCapacity += 5;
  }

  canCarry(quantity) {
    return Object.values(this.inventory).reduce((sum, q) => sum + q, 0) + quantity <= this.wagonCapacity;
  }
}

class Market {
  constructor(player) {
    this.player = player;
  }

  buyFromTown(town, good, quantity) {
    const price = town.getPrice(good);
    if (price !== null && this.player.buy(good, quantity, price)) {
      console.log(`Bought ${quantity} ${good} from ${town.name} for ${price} each.`);
      return true;
    }
    console.log(`Failed to buy ${quantity} ${good} from ${town.name}.`);
    return false;
  }

  sellToTown(town, good, quantity) {
    const price = town.getPrice(good);
    if (price !== null && this.player.sell(good, quantity, price)) {
      console.log(`Sold ${quantity} ${good} to ${town.name} for ${price} each.`);
      return true;
    }
    console.log(`Failed to sell ${quantity} ${good} to ${town.name}.`);
    return false;
  }
}

class EventSystem {
  constructor() {
    this.events = [
      { name: 'Bandits', effect: (player) => { player.money -= 10; console.log('Bandits stole 10 gold.'); } },
      { name: 'Broken Wheel', effect: () => { console.log('Wagon wheel broke. Travel time increased.'); } },
      { name: 'Lucky Merchant', effect: (player) => { player.money += 20; console.log('Met a lucky merchant. Earned 20 gold.'); } },
      { name: 'Market Boom', effect: (economy) => { economy.updatePrices(); console.log('Market boom! Prices increased.'); } },
      { name: 'Market Crash', effect: (economy) => { economy.updatePrices(); console.log('Market crash! Prices decreased.'); } }
    ];
  }

  generateEvent(player, economy) {
    const event = this.events[Math.floor(Math.random() * this.events.length)];
    console.log(`Random event: ${event.name}`);
    event.effect(player, economy);
  }
}

class Game {
  constructor() {
    this.economy = new Economy();
    this.towns = this.economy.towns.map(town => new Town(town.name, town.goods, town.supply, town.demand));
    this.player = new Player(100, {}, 10);
    this.market = new Market(this.player);
    this.eventSystem = new EventSystem();
    this.day = 0;
    this.running = true;
  }

  init() {
    console.log('Game initialized.');
    this.update();
  }

  update() {
    if (!this.running) return;
    this.day++;
    console.log(`Day ${this.day}: Starting day.`);
    this.economy.updatePrices();
    this.eventSystem.generateEvent(this.player, this.economy);
    setTimeout(() => this.update(), 1000); // Simulate daily cycle
  }

  save() {
    localStorage.setItem('gameState', JSON.stringify({
      day: this.day,
      player: this.player,
      economy: this.economy,
      towns: this.towns.map(town => ({ name: town.name, goods: town.goods, supply: town.supply, demand: town.demand }))
    }));
    console.log('Game saved.');
  }

  load() {
    const savedState = localStorage.getItem('gameState');
    if (savedState) {
      const state = JSON.parse(savedState);
      this.day = state.day;
      this.player = new Player(state.player.money, state.player.inventory, state.player.wagonCapacity);
      this.economy = new Economy();
      this.towns = state.towns.map(townData => new Town(townData.name, townData.goods, townData.supply, townData.demand));
      this.market = new Market(this.player);
      this.eventSystem = new EventSystem();
      console.log('Game loaded.');
    } else {
      console.log('No saved game found.');
    }
  }
}

class UI {
  constructor(game) {
    this.game = game;
    this.initUI();
  }

  initUI() {
    document.body.innerHTML = `
      <div id="game-container">
        <div id="town-view"></div>
        <div id="market-view"></div>
        <div id="travel-controls"></div>
        <div id="event-log"></div>
        <div id="statistics-panel"></div>
      </div>
    `;
    this.updateTownView();
    this.updateMarketView();
    this.updateTravelControls();
    this.updateStatisticsPanel();
  }

  updateTownView() {
    const townView = document.getElementById('town-view');
    townView.innerHTML = '<h2>Town View</h2>';
    this.game.towns.forEach(town => {
      const townElement = document.createElement('div');
      townElement.innerHTML = `<h3>${town.name}</h3>`;
      town.getGoodsInfo().forEach(goodInfo => {
        const goodElement = document.createElement('div');
        goodElement.innerHTML = `${goodInfo.good}: Supply ${goodInfo.supply}, Demand ${goodInfo.demand}`;
        townElement.appendChild(goodElement);
      });
      townView.appendChild(townElement);
    });
  }

  updateMarketView() {
    const marketView = document.getElementById('market-view');
    marketView.innerHTML = `
      <h2>Market View</h2>
      <button onclick="game.market.buyFromTown(game.towns[0], 'Grain', 1)">Buy Grain</button>
      <button onclick="game.market.sellToTown(game.towns[0], 'Grain', 1)">Sell Grain</button>
    `;
  }

  updateTravelControls() {
    const travelControls = document.getElementById('travel-controls');
    travelControls.innerHTML = `
      <h2>Travel Controls</h2>
      <button onclick="game.save()">Save Game</button>
      <button onclick="game.load()">Load Game</button>
    `;
  }

  updateStatisticsPanel() {
    const statisticsPanel = document.getElementById('statistics-panel');
    statisticsPanel.innerHTML = `
      <h2>Statistics Panel</h2>
      <p>Money: ${this.game.player.money}</p>
      <p>Inventory: ${JSON.stringify(this.game.player.inventory)}</p>
      <p>Wagon Capacity: ${this.game.player.wagonCapacity}</p>
      <p>Wagon Upgrades: ${this.game.player.wagonUpgrades}</p>
    `;
  }
}

