class Player {
  constructor(money = 100, inventory = {}, wagonCapacity = 10, wagonUpgrades = 0) {
    this.money = money;
    this.inventory = inventory;
    this.wagonCapacity = wagonCapacity;
    this.wagonUpgrades = wagonUpgrades;
  }

  buy(good, quantity, price) {
    if (this.money >= price * quantity && this.inventory[good] + quantity <= this.wagonCapacity) {
      this.money -= price * quantity;
      this.inventory[good] = (this.inventory[good] || 0) + quantity;
      return true;
    }
    return false;
  }

  sell(good, quantity, price) {
    if (this.inventory[good] >= quantity) {
      this.money += price * quantity;
      this.inventory[good] -= quantity;
      if (this.inventory[good] === 0) delete this.inventory[good];
      return true;
    }
    return false;
  }

  upgradeWagon() {
    this.wagonCapacity += 5;
    this.wagonUpgrades++;
  }
}

