  constructor(name, specialty){
    this.name = name;
    this.specialty = specialty;
    this.mod = 1;
  }
}

/* =========================
   ECONOMY SYSTEM
========================= */
class Economy {
  constructor(goods){
    this.goods = goods;
    this.basePrices = {};
    this.dailyPrices = {};

    goods.forEach(g=>{
      this.basePrices[g] = Math.floor(10 + Math.random()*40);
      this.dailyPrices[g] = this.basePrices[g];
    });
  }

  tickDay(){
    for(const g of this.goods){
      const drift = (Math.random()-0.5)*0.25;
      const spike = Math.random() < 0.08 ? (Math.random()*2+1) : 1;
      this.dailyPrices[g] = Math.max(1, Math.floor(this.dailyPrices[g]*(1+drift)*spike));
    }
  }

  getPrice(g, town){
    const base = this.dailyPrices[g];
    const mod = town.specialty === g ? 0.7 : 1.2;
    return Math.max(1, Math.floor(base * mod));
  }
}

/* =========================
   PLAYER SYSTEM
========================= */
class Player {
  constructor(){
    this.money = 500;
    this.cargo = {};
    this.capacity = 20;
    this.upgrades = {
      wagon: 0
    };
    this.stats = {
      profit: 0,
      trades: 0
    };
  }

  cargoUsed(){
    return Object.values(this.cargo).reduce((a,b)=>a+b,0);
  }

  canCarry(q){
    return this.cargoUsed() + q <= this.capacity;
  }

  addItem(g, q){
    this.cargo[g] = (this.cargo[g]||0)+q;
  }

  removeItem(g, q){
    this.cargo[g] -= q;
    if(this.cargo[g]<=0) delete this.cargo[g];
  }

  upgradeWagon(){
    const cost = 300 + this.upgrades.wagon*200;
    assert(this.money >= cost, "Not enough money");
    this.money -= cost;
    this.capacity += 10;
    this.upgrades.wagon++;
  }
}

/* =========================
   MARKET SYSTEM
========================= */
class Market {
  constructor(economy){
    this.economy = economy;
  }

  buy(player, town, g, q){
    const price = this.economy.getPrice(g, town)*q;
    assert(player.money >= price, "Not enough money");
    assert(player.canCarry(q), "Over capacity");

    player.money -= price;
    player.addItem(g,q);
    player.stats.trades++;
    player.stats.profit -= price;
  }

  sell(player, town, g, q){
    assert(player.cargo[g] >= q, "Not enough goods");
    const price = this.economy.getPrice(g, town)*q;

    player.money += price;
    player.removeItem(g,q);
    player.stats.trades++;
    player.stats.profit += price;
  }
}

/* =========================
   EVENT SYSTEM
========================= */
class EventSystem {
  constructor(game){
    this.game = game;
  }

  roll(){
    const r = Math.random();

    if(r < 0.2){
      this.bandits();
    } else if(r < 0.4){
      this.brokenWheel();
    } else if(r < 0.6){
      this.luckyMerchant();
    } else if(r < 0.8){
      this.marketBoom();
    } else {
      this.marketCrash();
    }
  }

  bandits(){
    const loss = Math.min(this.game.player.money, 50 + Math.floor(Math.random()*100));
    this.game.player.money -= loss;
    this.game.log(`Bandits robbed you for $${loss}`, false);
  }

  brokenWheel(){
    this.game.log("Wheel broke! Travel takes extra day.", false);
    this.game.pendingDelay += 1;
  }

  luckyMerchant(){
    const gain = 50 + Math.floor(Math.random()*100);
    this.game.player.money += gain;
    this.game.log(`Lucky merchant gave you $${gain}`, true);
  }

  marketBoom(){
    this.game.economy.goods.forEach(g=>{
      this.game.economy.dailyPrices[g] = Math.floor(this.game.economy.dailyPrices[g]*1.2);
    });
    this.game.log("Market boom! Prices rising.", true);
  }

  marketCrash(){
    this.game.economy.goods.forEach(g=>{
      this.game.economy.dailyPrices[g] = Math.floor(this.game.economy.dailyPrices[g]*0.8);
    });
    this.game.log("Market crash! Prices falling.", false);
  }
}

/* =========================
   GAME CORE
========================= */
class Game {
  constructor(){
    this.goods = ["grain","iron","spice","cloth","horses"];

    this.towns = [
      new Town("Red Ridge","iron"),
      new Town("Dustwater","grain"),
      new Town("Saltford","spice"),
      new Town("Green Hollow","cloth"),
      new Town("High Pasture","horses")
    ];

    this.economy = new Economy(this.goods);
    this.player = new Player();
    this.market = new Market(this.economy);
    this.events = new EventSystem(this);

    this.currentTown = this.towns[0];
    this.logLines = [];
    this.pendingDelay = 0;

    this.load();
    this.render();
    this.autoSave();
  }

  travelTo(town){
    if(this.pendingDelay > 0){
      this.log("You are delayed by repairs.", false);
      this.pendingDelay--;
      this.nextDay();
      return;
    }

    this.events.roll();
    this.currentTown = town;
    this.nextDay();
    this.log(`Traveled to ${town.name}`, true);
  }

  nextDay(){
    this.economy.tickDay();
  }

  log(msg, good){
    this.logLines.unshift({
      msg,
      good,
      t: new Date().toLocaleTimeString()
    });
    if(this.logLines.length>10) this.logLines.pop();
    this.render();
  }

  save(){
    localStorage.setItem("frontier_save", JSON.stringify({
      player:this.player,
      currentTown:this.currentTown.name,
      economy:this.economy.dailyPrices,
      stats:this.player.stats
    }));
  }

  load(){
    const s = localStorage.getItem("frontier_save");
    if(!s) return;
    try{
      const data = JSON.parse(s);
      this.player.money = data.player.money;
      this.player.capacity = data.player.capacity;
      this.player.cargo = data.player.cargo;
      this.player.stats = data.stats || this.player.stats;

      const t = this.towns.find(x=>x.name===data.currentTown);
      if(t) this.currentTown = t;

      if(data.economy){
        this.economy.dailyPrices = data.economy;
      }
    }catch(e){}
  }

  autoSave(){
    setInterval(()=>this.save(), 3000);
  }

  render(){
    const left = document.getElementById("left");
    const center = document.getElementById("center");
    const right = document.getElementById("right");

    /* LEFT PANEL */
    left.innerHTML = `
      <h3>Town</h3>
      <b>${this.currentTown.name}</b><br>
      Specialty: ${this.currentTown.specialty}
      <hr>
      ${this.towns.map(t=>`
        <button onclick="game.travelTo(game.towns[${this.towns.indexOf(t)}])">
          Travel to ${t.name}
        </button>
      `).join("")}

      <hr>
      <button onclick="game.player.upgradeWagon(); game.log('Upgraded wagon', true); game.render();">
        Upgrade Wagon ($${300 + this.player.upgrades.wagon*200})
      </button>
    `;

    /* CENTER MARKET */
    center.innerHTML = `
      <h3>Market</h3>
      <p class="small">Buy and sell goods in ${this.currentTown.name}</p>
      <hr>
      ${this.goods.map(g=>`
        <div>
          <b>${g}</b> - $${this.economy.getPrice(g,this.currentTown)}
          <br>
          <button onclick="game.market.buy(game.player,game.currentTown,'${g}',1)">Buy 1</button>
          <button onclick="game.market.sell(game.player,game.currentTown,'${g}',1)">Sell 1</button>
        </div>
      `).join("<hr>")}
    `;

    /* RIGHT PANEL */
    right.innerHTML = `
      <h3>Player</h3>
      Money: $${this.player.money}<br>
      Cargo: ${this.player.cargoUsed()}/${this.player.capacity}
      <hr>

      <h4>Cargo</h4>
      ${Object.entries(this.player.cargo).map(([g,q])=>`${g}: ${q}`).join("<br>") || "Empty"}

      <hr>
      <h4>Stats</h4>
      Profit: ${this.player.stats.profit}<br>
      Trades: ${this.player.stats.trades}

      <hr>
      <h4>Log</h4>
      ${this.logLines.map(l=>`
        <div class="${l.good?'good':'bad'}">
          [${l.t}] ${l.msg}
        </div>
      `).join("")}
    `;
  }
}

/* =========================
   BOOTSTRAP
========================= */
const game = new Game();
window.game = game;

/* =========================
   SELF CHECKS
========================= */
assert(game.goods.length === 5, "Must have 5 goods");
assert(game.towns.length === 5, "Must have 5 towns");

</script>

<!--
========================================================
FINAL ARCHITECTURE SUMMARY

1. System Interaction:
   Game orchestrates Player, Economy, Market, EventSystem.
   Player actions go through Market.
   Travel triggers EventSystem + Economy tick.

2. Why this architecture:
   - Prevents god-object state abuse
   - Keeps simulation systems independent
   - Makes balancing Economy safe without touching UI
   - Enables modular upgrades (wagon, towns, events)

3. Ownership:
   - Player: money, cargo, upgrades
   - Economy: pricing simulation
   - Town: identity + modifiers
   - Market: transactions only
   - EventSystem: travel randomness
   - Game: orchestration + UI + persistence

========================================================
-->
