            self.fertilizer -= 1
            self.plants[plant_index].grow(0, 1)
            return True
        return False

    def harvest_plant(self, plant_index):
        if plant_index < len(self.plants) and self.plants[plant_index].is_harvestable():
            del self.plants[plant_index]
            self.scoring_system.update_score(len(self.plants), self.calculate_resource_efficiency())
            return True
        return False

    def simulate_day(self):
        self.day += 1
        for plant in self.plants:
