function parse(input) {
  const result = {};

  for (const entry of input.split(';')) {
    const separator = entry.indexOf('=');
    if (separator === -1) {
      throw new Error(`Invalid entry: ${entry}`);
    }

    const key = entry.slice(0, separator);
    if (!key) {
      throw new Error('Keys must not be empty');
    }

    result[key] = entry.slice(separator + 1);
  }

  return result;
}

assert.deepStrictEqual(parse('a=1;b=2'), { a: '1', b: '2' });
console.log('All assertions passed.');

const assert = require('node:assert/strict');

const lines = [];

for (let number = 1; number <= 20; number += 1) {
  let line = '';

  if (number % 3 === 0) line += 'Fizz';
  if (number % 5 === 0) line += 'Buzz';

  lines.push(line || String(number));
}

assert.equal(lines[14], 'FizzBuzz', 'The 15th FizzBuzz line must be FizzBuzz');
console.log(lines.join('\n'));

